            dy = 0.0
            self.grasp_ref = (tr[0] - rx, tr[2] - ry)
            self.phase = "lift"
            self.last_cmd = (0, 0)
            return self._act(0, 0, dth, 0.0, vcmd)
        if self.phase == "lift":
            vcmd = 1.0
            if ry < travel_y - 1e-3:
                dy = min(travel_y - ry, self.max_dx)
            else:
                self.phase = "carry"
